<?php require __DIR__.'/includes/bootstrap.php';requireRole('attendee');$statement=$pdo->prepare('SELECT b.*,e.title,e.start_time,e.location,e.status FROM bookings b JOIN events e ON e.event_id=b.event_id WHERE b.user_id=? ORDER BY e.start_time ASC');$statement->execute([currentUser()['user_id']]);$bookings=$statement->fetchAll();$pageTitle='My bookings';require __DIR__.'/includes/header.php'; ?>
<h1>My bookings</h1><?php if(!$bookings):?><p class="notice">You have no bookings yet.</p><?php else:?><table><thead><tr><th>Event</th><th>When and where</th><th>Status</th><th class="no-print">Action</th></tr></thead><tbody><?php foreach($bookings as $booking):?><tr><td><a href="event.php?id=<?=(int)$booking['event_id']?>"><?=e($booking['title'])?></a></td><td><?=e(date('j M Y, H:i',strtotime($booking['start_time'])))?><br><?=e($booking['location'])?></td><td><?= $booking['checked_in']?'Checked in':'Confirmed' ?></td><td class="no-print"><form method="post" action="cancel_booking.php"><input type="hidden" name="booking_id" value="<?= (int)$booking['booking_id']?>"><button class="danger">Cancel booking</button></form></td></tr><?php endforeach?></tbody></table><?php endif;require __DIR__.'/includes/footer.php';
